SELECT pid, usename, state,
       now() - query_start AS dauer,
       left(query, 30) AS abfrage
FROM pg_stat_activity
WHERE state <> 'idle'
ORDER BY dauer DESC;

SELECT pg_cancel_backend(4125);

SELECT relname, n_live_tup,
       n_dead_tup, last_analyze
FROM pg_stat_user_tables;
